#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>

int abrir_cupom(const char *caminho) {
    int fd = open(caminho, O_WRONLY | O_APPEND | O_NOFOLLOW);
    struct stat st;
    if (fd < 0 || fstat(fd, &st) != 0 || !S_ISREG(st.st_mode)) { if (fd >= 0) close(fd); return -1; }
    return fd;
}

